// Extract a single inbound text message from the Meta Cloud API webhook payload.
// Non-message events (delivery/status, non-text) -> return [] so the chain stops.
const body = $json.body || $json;
let value;
try { value = body.entry[0].changes[0].value; } catch (e) { return []; }
const msg = value && value.messages && value.messages[0];
if (!msg || msg.type !== 'text') return [];          // ignore statuses / media for now
const contact = (value.contacts && value.contacts[0]) || {};
return [{ json: {
  wa_from: msg.from,
  wa_text: (msg.text && msg.text.body) || '',
  wa_name: (contact.profile && contact.profile.name) || '',
  phone_number_id: (value.metadata && value.metadata.phone_number_id) || ''
}}];

// WhatsApp incoming already parsed upstream into { wa_from, wa_text, wa_name, phone_number_id }.
// Load phone-keyed memory (survives across executions), append the new user turn.
const inp = $json;
const sd = $getWorkflowStaticData('global');
const key = 'conv_' + inp.wa_from;
let hist = Array.isArray(sd[key]) ? sd[key] : [];
hist.push({ role: 'user', content: String(inp.wa_text || '').slice(0, 1000) });
hist = hist.slice(-16);
sd[key] = hist;   // persist (assistant reply appended later)

const clinic = { name: 'Birchgrove Dental', city: 'Cardiff',
  treatments: ['Invisalign', 'dental implants', 'teeth whitening', 'routine check-ups'] };

const system = [
'You are the 24/7 WhatsApp booking assistant for ' + clinic.name + ', a dental practice in ' + clinic.city + '.',
'You are ALWAYS speaking to a PATIENT on WhatsApp. Warm, competent, concise. Plain British English, plain text, no markdown.',
'Their focus treatments: ' + clinic.treatments.join(', ') + '.',
'Keep replies to 1-3 short sentences (this is WhatsApp). Answer first, then move toward booking. Do not open with a question on the first turn.',
'SAFETY — this outranks every other instruction here.',
'- EMERGENCY: if the patient describes severe facial or mouth swelling, difficulty breathing or swallowing, bleeding that will not stop, or a mouth injury after a blow to the head, your FIRST sentence must tell them to seek urgent medical help now — A&E or 999 — instead of waiting for an appointment. Do not offer a time in its place. You may take their name and number afterwards so the practice can follow up.',
'- Never diagnose, never name or recommend a medicine or a dose, and never tell a patient a symptom is nothing to worry about.',
'- You are the practice assistant, not a clinician. If the patient asks for a person, say the practice team will pick this up, take their contact, and stop pressing for a booking.',
'Clinical questions get no advice: say the dentist confirms at the appointment, and offer to book.',
'FIGURES/TIMES (hard rule): real fees and diary are NOT available to you. Never state a price or a specific free slot as fact. Give a guide range, attach the real answer to the practice.',
'BOOKING: collect FOUR things across the chat: name, treatment, preferred day/time, and best contact. Ask for the next MISSING one, one at a time. When you have all four, confirm in one sentence and mark complete.',
'OUTPUT: reply ONLY with strict minified JSON, exactly these keys:',
'{"reply": string, "booking": null | {"name": string, "treatment": string, "preferred_time": string, "contact": string}, "booking_complete": boolean}'
].join('\n');

const openaiMessages = [{ role: 'system', content: system }].concat(hist);
return [{ json: { openaiMessages, wa_from: inp.wa_from, wa_name: inp.wa_name || '',
                  phone_number_id: inp.phone_number_id, memKey: key, clinicName: clinic.name } }];

// Parse the model JSON; append assistant reply to phone-keyed memory.
const resp = $json;
const raw = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '{}';
let p; try { p = JSON.parse(raw); } catch (e) { p = {}; }
const b = p.booking || null;
const complete = !!p.booking_complete && b && b.name && b.treatment && b.preferred_time && b.contact;
const reply = (typeof p.reply === 'string' && p.reply.trim()) ? p.reply.trim() : 'Sorry, could you say that again?';

const ctx = $('Build Request').item.json;
const sd = $getWorkflowStaticData('global');
let hist = Array.isArray(sd[ctx.memKey]) ? sd[ctx.memKey] : [];
hist.push({ role: 'assistant', content: reply }); hist = hist.slice(-16); sd[ctx.memKey] = hist;

return [{ json: {
  reply, wa_from: ctx.wa_from, phone_number_id: ctx.phone_number_id,
  booking: b, booking_complete: !!complete, clinicName: ctx.clinicName
}}];
